import React, { useState, useEffect } from 'react';
import api from '@landinghub/api';  // Giả sử api có các method getLeads, updateLead, deleteLead

const Leads = () => {
  const [leads, setLeads] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Lấy danh sách leads từ API
  const fetchLeads = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await api.getLeads();  // Giả sử trả về { data: [...] }
      setLeads(response.data);
    } catch (err) {
      setError('Lấy dữ liệu leads thất bại');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, []);

  // Cập nhật lead (status hoặc notes)
  const updateLead = async (id, field, value) => {
    try {
      await api.updateLead(id, { [field]: value });
      // Cập nhật local state để UI phản hồi nhanh
      setLeads(prev =>
        prev.map(lead => (lead._id === id ? { ...lead, [field]: value } : lead))
      );
    } catch (err) {
      alert('Cập nhật lead thất bại');
      console.error(err);
    }
  };

  // Xóa lead
  const deleteLead = async (id) => {
    if (!window.confirm('Bạn có chắc muốn xóa lead này?')) return;
    try {
      await api.deleteLead(id);
      setLeads(prev => prev.filter(lead => lead._id !== id));
    } catch (err) {
      alert('Xóa lead thất bại');
      console.error(err);
    }
  };

  if (loading) return <p>Đang tải dữ liệu leads...</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  return (
    <div>
      <h2>Quản lý Leads</h2>
      <table border="1" cellPadding="8" cellSpacing="0" style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th>Tên</th>
            <th>Email</th>
            <th>Điện thoại</th>
            <th>Trạng thái</th>
            <th>Ghi chú</th>
            <th>Hành động</th>
          </tr>
        </thead>
        <tbody>
          {leads.length === 0 && (
            <tr>
              <td colSpan="6" style={{ textAlign: 'center' }}>Chưa có lead nào</td>
            </tr>
          )}
          {leads.map(lead => (
            <tr key={lead._id}>
              <td>{lead.name}</td>
              <td>{lead.email}</td>
              <td>{lead.phone}</td>
              <td>
                <select
                  value={lead.status}
                  onChange={e => updateLead(lead._id, 'status', e.target.value)}
                >
                  <option value="new">Mới</option>
                  <option value="processing">Đang xử lý</option>
                  <option value="converted">Chuyển đổi</option>
                  <option value="lost">Mất</option>
                </select>
              </td>
              <td>
                <input
                  type="text"
                  value={lead.notes || ''}
                  onChange={e => updateLead(lead._id, 'notes', e.target.value)}
                  placeholder="Ghi chú"
                  style={{ width: '100%' }}
                />
              </td>
              <td>
                <button onClick={() => deleteLead(lead._id)} style={{ color: 'red' }}>
                  Xóa
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default React.memo(Leads);
